/// Append `values` onto the end of `arr`,
/// reusing `arr`'s buffer when possible.
///
/// Requires:  nothing special about the inputs.
/// Ensures:
///   1) The resulting length is the sum of the input lengths.
///   2) The content of the result is exactly the old `arr` followed by the old `values`.
#[requires(true)]
#[ensures(
    result.len() == old(arr.len()) + old(values.len())
)]
#[ensures(
    to_seq(&result)
        == to_seq(&old(arr)) + to_seq(&old(values))
)]
fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    // Start with the first vector by taking ownership of `arr`.
    // This lets us reuse its allocation when possible.
    let mut result = arr;
    
    // Reserve enough space for the elements of `values`
    // to avoid multiple reallocations.
    result.reserve(values.len());
    
    // Extend `result` by appending all elements from `values`.
    result.extend(values);
    
    result
}

